    ["This text is too long. Keep it under {max} characters."] = "Tento text je příliš dlouhý. Drž ho pod {max} znaků.",
    ["This text cannot be empty."] = "Tento text nesmí být prázdný.",
    ["Use a number from {min} to {max}."] = "Použij číslo od {min} do {max}.",
    ["Too many stop texts. Keep {max} or fewer."] = "Příliš mnoho stop textů. Nechej nejvýš {max}.",
