    ["{field}: {message}"] = "{field}: {message}",
    ["In use now"] = "Právě používáno",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "Jak má každá možnost konverzace odpovídat. Každá možnost má vlastní prompt. Změna platí od další odpovědi a nic se nemusí restartovat.",
    ["The facts the characters get from the game, the safety guards and the Mature rules cannot be edited here. Convai’s prompting lives on Convai’s side."] = "Fakta, která postavy dostávají od hry, bezpečnostní pojistky a pravidla pro obsah pro dospělé, zde nejde upravovat. Prompt Convai se řídí na straně Convai.",
    ["Mistral and Local AI"] = "Mistral a Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite a Standard jsou dvě velikosti modelu Local AI. Varianta „obsah pro dospělé“ se používá, když je obsah pro dospělé zapnutý.",
    ["Your Custom models and APIs"] = "Tvoje vlastní modely a API",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "Vlastní model se tady objeví, až zvolíš Vlastní jako poskytovatele konverzací a nastavíš model.",
    ["From {min} to {max}."] = "Od {min} do {max}.",
    ["Shipped: {value}"] = "Původní: {value}",
    ["Rule {n}"] = "Pravidlo {n}",
    ["Rule {n}, for a speaker with a reply length of its own"] = "Pravidlo {n}, pro postavu s vlastní délkou odpovědi",
    ["Rule {n}, for Mature content"] = "Pravidlo {n}, pro obsah pro dospělé",
    ["Move rule {n} up"] = "Pravidlo {n} nahoru",
