    ["Move down"] = "Dolů",
    ["Delete rule {n}"] = "Smazat pravidlo {n}",
    ["Other versions of this rule"] = "Jiné verze tohoto pravidla",
    ["Leave a version empty to use the rule text."] = "Nech verzi prázdnou, pokud má být použit text pravidla.",
    ["For a speaker with a reply length of its own"] = "Pro postavu s vlastní délkou odpovědi",
    ["For Mature content"] = "Pro obsah pro dospělé",
    ["Shipped: off"] = "Původní: vypnuto",
    ["Shipped: the mod’s own limit"] = "Původní: vlastní limit modu",
    ["before V’s words"] = "před slovy V",
    ["after V’s words"] = "za slovy V",
    ["Repeat the “where you are” sentence right before V’s words"] = "Zopakovat větu „kde jsi“ těsně před slovy V",
    ["The notes for this turn go"] = "Poznámky pro tuto odpověď jdou",
    ["Output rules"] = "Pravidla výstupu",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "Očíslovaná pravidla, která model čte před každou odpovědí. Použij {name} pro jméno postavy a {words} pro délku odpovědi postavy, která ji má.",
    ["Example replies"] = "Ukázkové odpovědi",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "Odpovědi, které se modelu ukážou po pravidlech. Malý model je může opsat slovo od slova, takže buď žádné nepřidej, nebo je nech krátké a jednoduché.",
    ["Add an example reply"] = "Přidat ukázkovou odpověď",
    ["An example reply"] = "Ukázková odpověď",
    ["Example reply {n}"] = "Ukázková odpověď {n}",
    ["Opening line"] = "Úvodní řádek",
    ["The first line of the character text. Use {name} for the character’s name."] = "První řádek textu postavy. Použij {name} pro jméno postavy.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "Poslední věc, kterou model přečte, než odpoví. Použij {name} pro jméno postavy a {words} pro délku odpovědi. Nastavení obsahu pro dospělé k ní přidá vlastní větu.",
    ["Section headings"] = "Nadpisy sekcí",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "Nadpisy, které označují každou část promptu. Měň znění, ne pořadí.",
    ["Layout"] = "Umístění",
    ["Where some notes go in the prompt."] = "Kam v promptu patří některé poznámky.",
    ["Sampling"] = "Vzorkování",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "Jak volně model formuluje odpověď. Nech pole prázdné, pokud má být použita původní hodnota.",
    ["Length limits"] = "Limity délky",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "Zkrať to, co model čte, a odpovědi budou rychlejší. Platí i vlastní limity modu, takže tohle může jen zkracovat.",
    ["Stop texts"] = "Stop texty",
    ["A reply ends when the model writes one of these. Line breaks count. Up to {max}."] = "Odpověď skončí, když model napíše jeden z těchto textů. Zalomení řádků se počítají. Nejvýš {max}.",
    ["Add a stop text"] = "Přidat stop text",
    ["A text that ends the reply"] = "Text, který ukončí odpověď",
    ["Stop text {n}"] = "Stop text {n}",
    ["Preview"] = "Náhled",
    ["The prompt text as the model would read it for a sample character. It follows your edits as you type, before you save."] = "Text promptu tak, jak by ho model četl pro ukázkovou postavu. Sleduje tvé úpravy, jak píšeš, ještě před uložením.",
    ["Sample character name"] = "Jméno ukázkové postavy",
    ["A speaker with a reply length of its own"] = "Postava s vlastní délkou odpovědi",
    ["Reply length in words"] = "Délka odpovědi ve slovech",
    ["Mature content is on"] = "Obsah pro dospělé zapnut",
    ["The preview waits until the problems in the form are fixed."] = "Náhled počká, dokud nebudou opraveny problémy ve formuláři.",
    ["No example replies."] = "Žádné ukázkové odpovědi.",
    ["No closing line."] = "Žádný závěrečný řádek.",
    ["Go back to the shipped prompting for {name}? Your changes to this part are removed."] = "Vrátit prompt postavy {name} k původnímu znění? Tvé změny v této části budou odstraněny.",
    ["Go back to the shipped prompting for {name}? All your changes to it are removed."] = "Vrátit prompt postavy {name} k původnímu znění? Všechny tvé změny v něm budou odstraněny.",
    ["Back to the shipped prompting."] = "Zpět na původní prompt.",
    ["Prompting"] = "Prompt",
    ["Street reputation"] = "Pouliční pověst",
    ["Gangs, the NCPD, corporations and the locals of each district remember what V did: Street Cred, choices in jobs, fights, crimes the police saw and how you treat people. It shapes their greeting, trust and help.\n\nOnly ordinary people, never named or story characters. It changes their words, nothing in the game."] = "Gangy, NCPD, korporace a místní z každé čtvrti si pamatují, co V udělal: Street Cred, rozhodnutí v zakázkách, boje, zločiny viděné policií a jak jednáš s lidmi. Podle toho zdraví, důvěřují a pomáhají.\n\nJen obyčejní lidé, nikdy pojmenované ani příběhové postavy. Mění jejich slova, nic ve hře.",
    ["Voice language"] = "Jazyk hlasu",
    ["English"] = "angličtina",
    ["Automatic"] = "Automaticky",
    ["Polish"] = "polština",
    ["Russian"] = "ruština",
    ["Ukrainian"] = "ukrajinština",
    ["Turkish"] = "turečtina",
    ["Czech"] = "čeština",
    ["Hungarian"] = "maďarština",
    ["Japanese"] = "japonština",
    ["Korean"] = "korejština",
    ["Chinese"] = "čínština",
    ["Choose one of the listed reply languages."] = "Vyberte jeden z uvedených jazyků odpovědí.",
    ["The language the characters speak. Counts only while Voice playback is on; with it off, replies follow what you write.\n\nAutomatic: follows what you write or say, and never changes on a short line.\n\nA voice that cannot speak the language shows the reply as text."] = "Jazyk, kterým postavy mluví. Platí jen při zapnutém Přehrávání hlasu; když je vypnuté, odpovědi se řídí tím, co píšeš.\n\nAutomaticky: řídí se tím, co píšeš nebo říkáš, a u krátké repliky se nikdy nemění.\n\nHlas, který daný jazyk neumí, zobrazí odpověď jako text.",
}
